mapper.update:
update wms_stock
warehouse_id = #{warehouseId}, product_id = #{productId}, location_id = #{locationId}, batch_no = #{batchNo}, expire_date = #{expireDate}, quantity = #{quantity}, locked_quantity = #{lockedQuantity}, frozen_quantity = #{frozenQuantity}, warning_min_qty = #{warningMinQty}, warning_max_qty = #{warningMaxQty}, version = #{version}, update_by = #{updateBy}, update_time = sysdate()
where stock_id = #{stockId}

update wms_stock
set quantity = ifnull(quantity, 0) - #{deltaQty},
    version = ifnull(version, 0) + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where stock_id = #{stockId}
  and ifnull(version, 0) = #{version}
  and (ifnull(quantity, 0) - ifnull(locked_quantity, 0) - ifnull(frozen_quantity, 0)) >= #{deltaQty}

update wms_stock
set locked_quantity = ifnull(locked_quantity, 0) + #{lockQty},
    version = ifnull(version, 0) + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where stock_id = #{stockId}
  and ifnull(version, 0) = #{version}
  and (ifnull(quantity, 0) - ifnull(locked_quantity, 0) - ifnull(frozen_quantity, 0)) >= #{lockQty}

update wms_stock
set quantity = ifnull(quantity, 0) - #{shipQty},
    locked_quantity = greatest(ifnull(locked_quantity, 0) - #{shipQty}, 0),
    version = ifnull(version, 0) + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where stock_id = #{stockId}
  and ifnull(version, 0) = #{version}
  and ifnull(quantity, 0) >= #{shipQty}

update wms_stock
set frozen_quantity = ifnull(frozen_quantity, 0) + #{freezeQty},
    version = ifnull(version, 0) + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where stock_id = #{stockId}
  and ifnull(version, 0) = #{version}
  and (ifnull(quantity, 0) - ifnull(locked_quantity, 0) - ifnull(frozen_quantity, 0)) >= #{freezeQty}

update wms_stock
set frozen_quantity = ifnull(frozen_quantity, 0) - #{unfreezeQty},
    version = ifnull(version, 0) + 1,
    update_by = #{updateBy},
    update_time = sysdate()
where stock_id = #{stockId}
  and ifnull(version, 0) = #{version}
  and ifnull(frozen_quantity, 0) >= #{unfreezeQty}
